import { setup, assign } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'addStaleLabelsToIssues',
  context: {
    owner: 'acme',
    repo: 'widgets',
    issueNumbers: [32, 34, 39, 43, 45, 47, 49, 51, 55, 58, 60, 64],
    issueLabels: {
      32: [],
      34: [],
      39: ['enhancement'],
      43: ['bug'],
      45: [],
      47: ['enhancement'],
      49: [],
      51: [],
      55: [],
      58: ['bug'],
      60: ['enhancement'],
      64: ['documentation', 'needs-triage'],
    },
    currentIndex: 0,
    results: [],
  },
  initial: 'updatingIssue',
  states: {
    updatingIssue: {
      entry: toolCall(
        'github.issue_write',
        ({ context }) => {
          const issueNumber = context.issueNumbers[context.currentIndex];
          const existingLabels = context.issueLabels[issueNumber] || [];
          const newLabels = Array.from(new Set([...existingLabels, 'stale']));

          return {
            method: 'update',
            owner: context.owner,
            repo: context.repo,
            issue_number: issueNumber,
            labels: newLabels,
          };
        },
        { id: 'updateCall' }
      ),
      on: {
        TOOL_RESULT: {
          guard: whenCall('updateCall'),
          target: 'checkNext',
          actions: assign({
            results: ({ context }) => [
              ...context.results,
              {
                issue: context.issueNumbers[context.currentIndex],
                status: 'updated',
              },
            ],
          }),
        },
        TOOL_DENIED: {
          target: 'checkNext',
          actions: assign({
            results: ({ context }) => [
              ...context.results,
              {
                issue: context.issueNumbers[context.currentIndex],
                status: 'declined',
              },
            ],
          }),
        },
        TOOL_ERROR: {
          target: 'checkNext',
          actions: assign({
            results: ({ context, event }) => [
              ...context.results,
              {
                issue: context.issueNumbers[context.currentIndex],
                status: 'error',
                error: event.error,
              },
            ],
          }),
        },
      },
    },
    checkNext: {
      entry: assign({
        currentIndex: ({ context }) => context.currentIndex + 1,
      }),
      always: [
        {
          guard: ({ context }) => context.currentIndex >= context.issueNumbers.length,
          target: 'done',
        },
        {
          target: 'updatingIssue',
        },
      ],
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    totalUpdated: context.results.filter(r => r.status === 'updated').length,
    totalDeclined: context.results.filter(r => r.status === 'declined').length,
    totalErrors: context.results.filter(r => r.status === 'error').length,
    results: context.results,
  }),
});

