import { setup, assign } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'addStaleLabels',
  context: {
    owner: 'acme',
    repo: 'widgets',
    cutoffDate: '2026-07-01',
    allIssues: [],
    issuesNeedingLabel: [],
    currentUpdateIndex: 0,
    approvalsSummary: [],
  },
  initial: 'fetchingIssues',
  states: {
    fetchingIssues: {
      entry: toolCall('github.list_issues', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'OPEN',
        perPage: 100,
        fields: ['number', 'title', 'labels', 'updated_at'],
      }), { id: 'listIssues' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('listIssues'),
          target: 'processingIssues',
          actions: assign({
            allIssues: ({ event }) => event.result.issues || event.result?.data?.issues || [],
          }),
        },
        TOOL_ERROR: {
          target: 'failed',
          actions: assign({
            approvalsSummary: ({ event }) => [{ error: `Failed to fetch issues: ${event.error}` }],
          }),
        },
      },
    },
    processingIssues: {
      entry: assign({
        issuesNeedingLabel: ({ context }) => {
          const cutoff = new Date(context.cutoffDate);
          return context.allIssues.filter(issue => {
            const updatedDate = new Date(issue.updated_at);
            return updatedDate < cutoff;
          });
        },
      }),
      always: {
        target: 'checkIfUpdatesNeeded',
      },
    },
    checkIfUpdatesNeeded: {
      always: [
        {
          guard: ({ context }) => context.issuesNeedingLabel.length === 0,
          target: 'done',
          actions: assign({
            approvalsSummary: () => [{ message: 'No open issues found that need the stale label.' }],
          }),
        },
        {
          target: 'updatingIssue',
        },
      ],
    },
    updatingIssue: {
      entry: ({ context }) => {
        const issue = context.issuesNeedingLabel[context.currentUpdateIndex];
        const existingLabels = (issue.labels || []).map(l => typeof l === 'string' ? l : l.name);
        const newLabels = Array.from(new Set([...existingLabels, 'stale']));
        return toolCall('github.issue_write', {
          method: 'update',
          owner: context.owner,
          repo: context.repo,
          issue_number: issue.number,
          labels: newLabels,
        }, { id: `updateIssue${context.currentUpdateIndex}` });
      },
      on: {
        TOOL_RESULT: {
          guard: ({ context }) => whenCall(`updateIssue${context.currentUpdateIndex}`)({}),
          target: 'moveToNextIssue',
          actions: assign({
            approvalsSummary: ({ context, event }) => [
              ...context.approvalsSummary,
              {
                issueNumber: context.issuesNeedingLabel[context.currentUpdateIndex].number,
                status: 'updated',
              },
            ],
          }),
        },
        TOOL_DENIED: {
          target: 'moveToNextIssue',
          actions: assign({
            approvalsSummary: ({ context, event }) => [
              ...context.approvalsSummary,
              {
                issueNumber: context.issuesNeedingLabel[context.currentUpdateIndex].number,
                status: 'declined',
                reason: event.reason,
              },
            ],
          }),
        },
        TOOL_ERROR: {
          target: 'moveToNextIssue',
          actions: assign({
            approvalsSummary: ({ context, event }) => [
              ...context.approvalsSummary,
              {
                issueNumber: context.issuesNeedingLabel[context.currentUpdateIndex].number,
                status: 'error',
                error: event.error,
              },
            ],
          }),
        },
      },
    },
    moveToNextIssue: {
      entry: assign({
        currentUpdateIndex: ({ context }) => context.currentUpdateIndex + 1,
      }),
      always: [
        {
          guard: ({ context }) => context.currentUpdateIndex >= context.issuesNeedingLabel.length,
          target: 'done',
        },
        {
          target: 'updatingIssue',
        },
      ],
    },
    done: {
      type: 'final',
    },
    failed: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    totalOpenIssues: context.allIssues.length,
    staleIssuesFound: context.issuesNeedingLabel.length,
    staleIssueNumbers: context.issuesNeedingLabel.map(i => i.number),
    updates: context.approvalsSummary,
  }),
});

