export default setup({}).createMachine({
  id: 'identifyStaleIssues',
  context: {
    owner: 'acme',
    repo: 'widgets',
    cutoffDate: '2026-07-01',
    allIssues: [],
    issuesNeedingLabel: [],
  },
  initial: 'fetchingIssues',
  states: {
    fetchingIssues: {
      entry: toolCall('github.list_issues', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'OPEN',
        perPage: 100,
        fields: ['number', 'title', 'labels', 'updated_at'],
      }), { id: 'listIssues' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('listIssues'),
          target: 'filteringIssues',
          actions: assign({
            allIssues: ({ event }) => {
              let result = event.result;
              if (typeof result === 'string') {
                result = JSON.parse(result);
              }
              return result.issues || [];
            },
          }),
        },
        TOOL_ERROR: {
          target: 'failed',
        },
      },
    },
    filteringIssues: {
      entry: assign({
        issuesNeedingLabel: ({ context }) => {
          const cutoff = context.cutoffDate;
          return context.allIssues.filter(issue => {
            return issue.updated_at < cutoff;
          });
        },
      }),
      always: {
        target: 'done',
      },
    },
    done: {
      type: 'final',
    },
    failed: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    totalOpenIssues: context.allIssues.length,
    staleIssuesFound: context.issuesNeedingLabel.length,
    staleIssueNumbers: context.issuesNeedingLabel.map(i => i.number).sort((a, b) => a - b),
    staleIssueDetails: context.issuesNeedingLabel.map(i => ({
      number: i.number,
      title: i.title,
      updated_at: i.updated_at,
      currentLabels: (i.labels || []).map(l => typeof l === 'string' ? l : l.name),
    })),
  }),
});

