export default setup({}).createMachine({
  id: 'verifyAllStaleIssues',
  context: {
    issueNumbers: [32, 34, 39, 43, 45, 47, 49, 51, 55, 58, 60, 64],
    issueDetails: [],
  },
  initial: 'fetchingIssues',
  states: {
    fetchingIssues: {
      entry: toolCall('github.list_issues', ({}) => ({
        owner: 'acme',
        repo: 'widgets',
        state: 'OPEN',
        perPage: 100,
      }), { id: 'listIssues' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('listIssues'),
          target: 'done',
          actions: assign({
            issueDetails: ({ event, context }) => {
              let result = event.result;
              if (typeof result === 'string') {
                result = JSON.parse(result);
              }
              const issues = result.issues || [];
              return issues
                .filter(i => context.issueNumbers.includes(i.number))
                .map(i => ({
                  number: i.number,
                  title: i.title,
                  labels: (i.labels || []).map(l => typeof l === 'string' ? l : l.name),
                  hasStale: (i.labels || []).some(l => (typeof l === 'string' ? l : l.name) === 'stale'),
                }))
                .sort((a, b) => a.number - b.number);
            },
          }),
        },
      },
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => context.issueDetails,
});

