import { setup, assign } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'commentOnExportPRs',
  context: {
    owner: 'acme',
    repo: 'widgets',
    openPRs: [] as any[],
    prIndex: 0,
    filesChecked: {} as Record<number, boolean>,
    commentedPRs: [] as number[],
  },
  initial: 'listingPRs',
  states: {
    listingPRs: {
      entry: toolCall('github.list_pull_requests', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'open',
        fields: ['number', 'title', 'html_url']
      }), { id: 'listPRs' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('listPRs'),
          target: 'processingPRs',
          actions: assign({
            openPRs: ({ event }) => {
              const result = event.result;
              // Result should be an array of PRs
              if (Array.isArray(result)) {
                return result;
              }
              // Handle case where result might be wrapped
              return result?.pullRequests || result?.items || [];
            }
          })
        },
        TOOL_ERROR: {
          guard: whenCall('listPRs'),
          target: 'done'
        }
      }
    },
    processingPRs: {
      on: {
        CHECK_NEXT: [
          {
            guard: ({ context }) => context.prIndex < context.openPRs.length,
            target: 'checkingFiles'
          },
          {
            target: 'done'
          }
        ]
      },
      entry: () => { /* Will immediately transition */ },
      initial: 'checkIfMorePRs',
      states: {
        checkIfMorePRs: {
          always: {
            target: '#commentOnExportPRs.processingPRs',
            actions: assign({
              prIndex: ({ context }) => context.prIndex + 1
            })
          }
        }
      }
    },
    checkingFiles: {
      entry: toolCall('github.pull_request_read', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        pullNumber: context.openPRs[context.prIndex].number,
        method: 'get_files',
        perPage: 100
      }), { id: 'getFiles' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('getFiles'),
          target: 'decidingComment',
          actions: assign({
            filesChecked: ({ context, event }) => {
              const prNumber = context.openPRs[context.prIndex].number;
              const result = event.result;

              // Extract files list
              let files = [];
              if (Array.isArray(result)) {
                files = result;
              } else if (result?.files) {
                files = result.files;
              }

              // Check if any file is under src/export/
              const hasExportFile = files.some((file: any) => {
                const filename = file.filename || '';
                return filename.startsWith('src/export/');
              });

              return {
                ...context.filesChecked,
                [prNumber]: hasExportFile
              };
            }
          })
        },
        TOOL_ERROR: {
          guard: whenCall('getFiles'),
          target: 'processingPRs'
        }
      }
    },
    decidingComment: {
      always: [
        {
          guard: ({ context }) => {
            const prNumber = context.openPRs[context.prIndex].number;
            return context.filesChecked[prNumber] === true;
          },
          target: 'postingComment'
        },
        {
          target: 'processingPRs'
        }
      ]
    },
    postingComment: {
      entry: toolCall('github.add_issue_comment', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        issue_number: context.openPRs[context.prIndex].number,
        body: 'Please add a CHANGELOG entry for the export changes.'
      }), { id: 'postComment' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('postComment'),
          target: 'processingPRs',
          actions: assign({
            commentedPRs: ({ context }) => [
              ...context.commentedPRs,
              context.openPRs[context.prIndex].number
            ]
          })
        },
        TOOL_DENIED: {
          guard: whenCall('postComment'),
          target: 'processingPRs'
        },
        TOOL_ERROR: {
          guard: whenCall('postComment'),
          target: 'processingPRs'
        }
      }
    },
    done: { type: 'final' }
  },
  output: ({ context }) => ({
    totalPRsChecked: context.openPRs.length,
    prsCommented: context.commentedPRs,
    commentCount: context.commentedPRs.length
  })
});

