      entry: toolCall('github.list_pull_requests', () => ({
        owner: 'acme',
        repo: 'widgets',
        state: 'open'
      }), { id: 'listPRs' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('listPRs'),
          target: 'loopThroughPRs',
          actions: assign({
            openPRs: ({ event }) => {
              const result = event.result;
              return Array.isArray(result) ? result : [];
            }
          })
        },
        TOOL_ERROR: {
          guard: whenCall('listPRs'),
          target: 'done'
        }
      }
    },
    loopThroughPRs: {
      always: [
        {
          guard: ({ context }) => context.currentIndex < context.openPRs.length,
          target: 'checkPRFiles'
        },
        {
          target: 'done'
        }
      ]
    },
    checkPRFiles: {
      entry: toolCall('github.pull_request_read', ({ context }) => {
        const pr = context.openPRs[context.currentIndex];
        return {
          owner: 'acme',
          repo: 'widgets',
          pullNumber: pr.number,
          method: 'get_files',
          perPage: 100
        };
      }, { id: 'getFiles' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('getFiles'),
          target: 'processFiles',
          actions: assign({
            prFilesMap: ({ context, event }) => {
              const pr = context.openPRs[context.currentIndex];
              const result = event.result;

              let files = [];
              if (Array.isArray(result)) {
                files = result;
              } else if (result?.files) {
                files = result.files;
              }

              return {
                ...context.prFilesMap,
                [pr.number]: files
              };
            }
          })
        },
        TOOL_ERROR: {
          guard: whenCall('getFiles'),
          target: 'incrementIndex'
        }
      }
    },
    processFiles: {
      always: [
        {
          guard: ({ context }) => {
            const pr = context.openPRs[context.currentIndex];
            const files = context.prFilesMap[pr.number] || [];
            return files.some(f => {
              const filename = f.filename || '';
              return filename.startsWith('src/export/');
            });
          },
          target: 'postComment'
        },
        {
          target: 'incrementIndex'
        }
      ]
    },
    postComment: {
      entry: toolCall('github.add_issue_comment', ({ context }) => {
        const pr = context.openPRs[context.currentIndex];
        return {
          owner: 'acme',
          repo: 'widgets',
          issue_number: pr.number,
          body: 'Please add a CHANGELOG entry for the export changes.'
        };
      }, { id: 'postComment' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('postComment'),
          target: 'incrementIndex',
          actions: assign({
            commentedPRs: ({ context }) => [
              ...context.commentedPRs,
              context.openPRs[context.currentIndex].number
            ]
          })
        },
        TOOL_DENIED: {
          guard: whenCall('postComment'),
          target: 'incrementIndex'
        },
        TOOL_ERROR: {
          guard: whenCall('postComment'),
          target: 'incrementIndex'
        }
      }
    },
    incrementIndex: {
      always: {
        target: 'loopThroughPRs',
        actions: assign({
          currentIndex: ({ context }) => context.currentIndex + 1
        })
      }
    },
    done: { type: 'final' }
  },
  output: ({ context }) => ({
    totalPRsChecked: context.openPRs.length,
    prsCommented: context.commentedPRs,
    commentCount: context.commentedPRs.length
  })
});

import { setup, assign } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'commentOnExportPRs',
  context: {
    owner: 'acme',
    repo: 'widgets',
    openPRs: [],
    index: 0,
    commentedPRs: [],
  },
  initial: 'fetchPRs',
  states: {
    fetchPRs: {
      entry: toolCall('github.list_pull_requests', () => ({
        owner: 'acme',
        repo: 'widgets',
        state: 'open'
      }), { id: 'listPRs' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('listPRs'),
          target: 'checkNextPR',
          actions: assign({
            openPRs: ({ event }) => Array.isArray(event.result) ? event.result : []
          })
        },
        TOOL_ERROR: {
          guard: whenCall('listPRs'),
          target: 'done'
        }
      }
    },
    checkNextPR: {
      always: [
        {
          guard: ({ context }) => context.index < context.openPRs.length,
          target: 'fetchPRFiles'
        },
        {
          target: 'done'
        }
      ]
    },
    fetchPRFiles: {
      entry: toolCall('github.pull_request_read', ({ context }) => ({
        owner: 'acme',
        repo: 'widgets',
        pullNumber: context.openPRs[context.index].number,
        method: 'get_files',
        perPage: 100
      }), { id: 'files' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('files'),
          target: 'checkForExportFiles',
          actions: assign({})
        },
        TOOL_ERROR: {
          guard: whenCall('files'),
          target: 'nextPR'
        }
      }
    },
    checkForExportFiles: {
      always: [
        {
          guard: ({ event }) => {
            const files = Array.isArray(event.result) ? event.result : event.result?.files || [];
            return files.some(f => (f.filename || '').startsWith('src/export/'));
          },
          target: 'addComment'
        },
        {
          target: 'nextPR'
        }
      ]
    },
    addComment: {
      entry: toolCall('github.add_issue_comment', ({ context }) => ({
        owner: 'acme',
        repo: 'widgets',
        issue_number: context.openPRs[context.index].number,
        body: 'Please add a CHANGELOG entry for the export changes.'
      }), { id: 'comment' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('comment'),
          target: 'nextPR',
          actions: assign({
            commentedPRs: ({ context }) => [...context.commentedPRs, context.openPRs[context.index].number]
          })
        },
        TOOL_DENIED: {
          guard: whenCall('comment'),
          target: 'nextPR'
        },
        TOOL_ERROR: {
          guard: whenCall('comment'),
          target: 'nextPR'
        }
      }
    },
    nextPR: {
      always: {
        target: 'checkNextPR',
        actions: assign({
          index: ({ context }) => context.index + 1
        })
      }
    },
    done: { type: 'final' }
  },
  output: ({ context }) => ({
    totalPRsChecked: context.openPRs.length,
    prsCommented: context.commentedPRs,
    commentCount: context.commentedPRs.length
  })
});

import { setup, assign } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'commentOnExportPRs',
  context: {
    openPRs: [],
    index: 0,
    commentedPRs: [],
    currentFilesList: null
  },
  initial: 'fetchPRs',
  states: {
    fetchPRs: {
      entry: toolCall('github.list_pull_requests', () => ({
        owner: 'acme',
        repo: 'widgets',
        state: 'open'
      }), { id: 'listPRs' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('listPRs'),
          target: 'checkNextPR',
          actions: assign({
            openPRs: ({ event }) => {
              const result = event.result;
              return Array.isArray(result) ? result : (result?.pullRequests || result?.items || []);
            },
            index: 0,
            commentedPRs: [],
            currentFilesList: null
          })
        },
        TOOL_ERROR: {
          guard: whenCall('listPRs'),
          target: 'done'
        }
      }
    },
    checkNextPR: {
      always: [
        {
          guard: ({ context }) => context.index < context.openPRs.length,
          target: 'fetchPRFiles'
        },
        {
          target: 'done'
        }
      ]
    },
    fetchPRFiles: {
      entry: toolCall('github.pull_request_read', ({ context }) => ({
        owner: 'acme',
        repo: 'widgets',
        pullNumber: context.openPRs[context.index].number,
        method: 'get_files',
        perPage: 100
      }), { id: 'files' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('files'),
          target: 'analyzeFiles',
          actions: assign({
            currentFilesList: ({ event }) => {
              const result = event.result;
              return Array.isArray(result) ? result : (result?.files || []);
            }
          })
        },
        TOOL_ERROR: {
          guard: whenCall('files'),
          target: 'nextPR'
        }
      }
    },
    analyzeFiles: {
      always: [
        {
          guard: ({ context }) => {
            if (!context.currentFilesList) return false;
            return context.currentFilesList.some(f => (f.filename || '').startsWith('src/export/'));
          },
          target: 'addComment'
        },
        {
          target: 'nextPR'
        }
      ]
    },
    addComment: {
      entry: toolCall('github.add_issue_comment', ({ context }) => ({
        owner: 'acme',
        repo: 'widgets',
        issue_number: context.openPRs[context.index].number,
        body: 'Please add a CHANGELOG entry for the export changes.'
      }), { id: 'comment' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('comment'),
          target: 'nextPR',
          actions: assign({
            commentedPRs: ({ context }) => [
              ...context.commentedPRs,
              context.openPRs[context.index].number
            ]
          })
        },
        TOOL_DENIED: {
          guard: whenCall('comment'),
          target: 'nextPR'
        },
        TOOL_ERROR: {
          guard: whenCall('comment'),
          target: 'nextPR'
        }
      }
    },
    nextPR: {
      always: {
        target: 'checkNextPR',
        actions: assign({
          index: ({ context }) => context.index + 1,
          currentFilesList: null
        })
      }
    },
    done: { type: 'final' }
  },
  output: ({ context }) => ({
    totalPRsChecked: context.openPRs.length,
    prsCommented: context.commentedPRs,
    commentCount: context.commentedPRs.length
  })
});

