Tool "mongo.find" in the mongo box
Posture: runs immediately
Title (server-provided): "find"
What the server says it does:
    Run a find query against a MongoDB collection

Input schema (JSON Schema):
    {
      "type": "object",
      "properties": {
        "connectionId": {
          "type": "string",
          "description": "The connection to run the operation against. Use the id returned by one of the connect tools, or \"preconfigured\" to use the connection string the server was configured with."
        },
        "database": {
          "type": "string",
          "description": "Database name"
        },
        "collection": {
          "type": "string",
          "description": "Collection name"
        },
        "filter": {
          "description": "The query filter, matching the syntax of the query argument of db.collection.find()",
          "type": "object",
          "properties": {},
          "additionalProperties": {}
        },
        "projection": {
          "description": "The projection, matching the syntax of the projection argument of db.collection.find()",
          "type": "object",
          "properties": {},
          "additionalProperties": {}
        },
        "limit": {
          "description": "The maximum number of documents to return",
          "type": "number"
        },
        "sort": {
          "description": "A document, describing the sort order, matching the syntax of the sort argument of cursor.sort(). The keys of the object are the fields to sort on, while the values are the sort directions (1 for ascending, -1 for descending).",
          "type": "object",
          "additionalProperties": {
            "anyOf": [
              {
                "type": "number",
                "const": 1
              },
              {
                "type": "number",
                "const": -1
              },
              {
                "type": "string",
                "const": "asc"
              },
              {
                "type": "string",
                "const": "desc"
              },
              {
                "type": "string",
                "const": "ascending"
              },
              {
                "type": "string",
                "const": "descending"
              },
              {
                "type": "object",
                "properties": {
                  "$meta": {
                    "type": "string"
                  }
                },
                "required": [
                  "$meta"
                ]
              }
            ],
            "description": "The sort key and its direction"
          }
        },
        "responseBytesLimit": {
          "description": "The maximum number of bytes to return in the response. This value is capped by the server's configured maximum and cannot be exceeded.",
          "type": "number"
        }
      },
      "required": [
        "connectionId",
        "database",
        "collection"
      ],
      "additionalProperties": false
    }

Output schema (JSON Schema):
    {
      "type": "object",
      "properties": {
        "documents": {
          "type": "array",
          "items": {},
          "description": "The documents returned by the find query"
        },
        "queryResultsCount": {
          "description": "The total number of documents returned by the find query",
          "type": "number"
        },
        "appliedLimits": {
          "type": "array",
          "items": {
            "type": "string",
            "enum": [
              "config.maxDocumentsPerQuery",
              "config.maxBytesPerQuery",
              "tool.responseBytesLimit"
            ]
          },
          "description": "The limits applied to the find query"
        }
      },
      "required": [
        "documents",
        "appliedLimits"
      ],
      "additionalProperties": false
    }

