import { setup, assign } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'processVIPs',
  context: ({ input }) => {
    const emails = input.emails.filter((e: string) => e.trim() && !e.startsWith('#'));
    return {
      emails,
      currentIndex: 0,
      missingVips: [] as string[],
    };
  },
  initial: 'processEmails',
  states: {
    processEmails: {
      always: [
        {
          guard: ({ context }) => context.currentIndex >= context.emails.length,
          target: 'writeMissingVips',
        },
        {
          target: 'checkCustomer',
        },
      ],
    },
    checkCustomer: {
      entry: toolCall(
        'mongo.find',
        ({ context }) => ({
          connectionId: 'preconfigured',
          database: 'shop',
          collection: 'customers',
          filter: { email: context.emails[context.currentIndex] },
          projection: { _id: 1, tier: 1, email: 1 },
          limit: 1,
        }),
        { id: 'findCustomer' }
      ),
      on: {
        TOOL_RESULT: [
          {
            guard: ({ event }) => (event.result as any).queryResultsCount > 0,
            target: 'updateTier',
          },
          {
            target: 'addToMissing',
          },
        ],
        TOOL_ERROR: {
          target: 'addToMissing',
        },
      },
    },
    updateTier: {
      entry: toolCall(
        'mongo.update-many',
        ({ context }) => ({
          connectionId: 'preconfigured',
          database: 'shop',
          collection: 'customers',
          filter: { email: context.emails[context.currentIndex] },
          update: { $set: { tier: 'gold' } },
        }),
        { id: 'updateCustomer' }
      ),
      on: {
        TOOL_RESULT: {
          target: 'nextEmail',
        },
        TOOL_DENIED: {
          target: 'nextEmail',
        },
        TOOL_ERROR: {
          target: 'nextEmail',
        },
      },
    },
    addToMissing: {
      entry: assign({
        missingVips: ({ context }) => [
          ...context.missingVips,
          context.emails[context.currentIndex],
        ],
      }),
      always: 'nextEmail',
    },
    nextEmail: {
      entry: assign({
        currentIndex: ({ context }) => context.currentIndex + 1,
      }),
      always: 'processEmails',
    },
    writeMissingVips: {
      entry: toolCall(
        'fs.write_file',
        ({ context }) => ({
          path: 'notes/missing-vips.txt',
          content: context.missingVips.join('\n'),
          append: false,
        }),
        { id: 'writeMissing' }
      ),
      on: {
        TOOL_RESULT: {
          target: 'done',
        },
        TOOL_DENIED: {
          target: 'done',
        },
        TOOL_ERROR: {
          target: 'done',
        },
      },
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    processed: context.emails.length,
    missingCount: context.missingVips.length,
    missingVips: context.missingVips,
  }),
});

