import { setup, assign } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'c',
  context: { prs: [146,144,142,140,139,137,12,11,135,10,134,8,132,131,128,127,125,124,123,121,120,117,116,114,113,111], i: 0, done: [] as number[] },
  initial: 'check',
  states: {
    check: {
      always: { guard: ({context}) => context.i >= context.prs.length, target: 'end' },
      entry: toolCall('github.pull_request_read', ({context}) => ({ method: 'get_files', owner: 'acme', repo: 'widgets', pullNumber: context.prs[context.i], perPage: 100 })),
      on: {
        TOOL_RESULT: [
          { guard: ({event}) => {
              const r: any = event.result;
              const a = typeof r === 'string' ? JSON.parse(r) : r;
              return a.some((f: any) => f.filename.startsWith('src/export/'));
            }, target: 'comment' },
          { target: 'check', reenter: true, actions: assign({ i: ({context}) => context.i + 1 }) },
        ],
        TOOL_ERROR: { target: 'check', reenter: true, actions: assign({ i: ({context}) => context.i + 1 }) },
      },
    },
    comment: {
      entry: toolCall('github.add_issue_comment', ({context}) => ({ owner: 'acme', repo: 'widgets', issue_number: context.prs[context.i], body: 'Please add a CHANGELOG entry for the export changes.' })),
      on: {
        TOOL_RESULT: { target: 'check', actions: assign({ done: ({context}) => [...context.done, context.prs[context.i]], i: ({context}) => context.i + 1 }) },
        TOOL_DENIED: { target: 'check', actions: assign({ i: ({context}) => context.i + 1 }) },
        TOOL_ERROR: { target: 'check', actions: assign({ i: ({context}) => context.i + 1 }) },
      },
    },
    end: { type: 'final' },
  },
  output: ({context}) => context.done,
});

import { setup, assign } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'c',
  context: { prs: [146,144,142,140,139,137,12,11,135,10,134,8,132,131,128,127,125,124,123,121,120,117,116,114,113,111], i: 0, hit: [] as number[], commented: [] as number[], stage: 0 },
  initial: 'check',
  states: {
    check: {
      always: { guard: ({context}) => context.i >= context.prs.length, target: 'end' },
      entry: toolCall('github.pull_request_read', ({context}) => ({ method: 'get_files', owner: 'acme', repo: 'widgets', pullNumber: context.prs[context.i], perPage: 100 })),
      on: {
        TOOL_RESULT: { target: 'check', reenter: true, actions: assign({
          hit: ({context, event}) => {
            const r: any = event.result;
            const a = typeof r === 'string' ? JSON.parse(r) : r;
            return a.some((f: any) => f.filename.startsWith('src/export/')) ? [...context.hit, context.prs[context.i]] : context.hit;
          },
          i: ({context}) => context.i + 1 }) },
        TOOL_ERROR: { target: 'check', reenter: true, actions: assign({ i: ({context}) => context.i + 1 }) },
      },
    },
    end: { type: 'final' },
  },
  output: ({context}) => context.hit,
});

