        "appliedLimits": {
          "type": "array",
          "items": {
            "type": "string",
            "enum": [
              "config.maxDocumentsPerQuery",
              "config.maxBytesPerQuery",
              "tool.responseBytesLimit"
            ]
          },
          "description": "The limits applied to the aggregation pipeline"
        }
      },
      "required": [
        "documents",
        "count",
        "appliedLimits"
      ],
      "additionalProperties": false
    }

