import { setup, assign } from 'xstate';
import { toolCall } from '@astral-mcp/tools';
const files = ["api-gateway","auth","billing","cart","catalog","checkout","email","fraud","geo","image","inventory","ledger","loyalty","media","notify","orders","payments","pricing","profile","queue","ranking","recs","reviews","search","session","shipping","tax","wishlist"];
export default setup({}).createMachine({
  id: 'c',
  context: { i: 0, out: [] as string[] },
  initial: 'r',
  states: {
    r: {
      entry: toolCall('fs.read_text_file', ({ context }) => ({ path: 'logs/services/' + files[context.i] + '.log' })),
      on: {
        TOOL_RESULT: { target: 'n', actions: assign({ out: ({ context, event }) => {
          const res: any = event.result;
          const t: string = typeof res === 'string' ? res : (res && res.content) || JSON.stringify(res);
          const n = t.split('\n').filter((l: string) => l.trim().split(/\s+/)[1] === 'ERROR').length;
          return [...context.out, files[context.i] + '.log: ' + n];
        }, i: ({ context }) => context.i + 1 }) },
        TOOL_ERROR: { target: 'n', actions: assign({ out: ({ context }) => [...context.out, files[context.i] + '.log: error'], i: ({ context }) => context.i + 1 }) },
      },
    },
    n: { always: [{ guard: ({ context }) => context.i >= files.length, target: 'd' }, { target: 'r' }] },
    d: { type: 'final' },
  },
  output: ({ context }) => context.out,
});

